<?php
require_once __DIR__.'/includes/functions.php';require_once __DIR__.'/config/database.php';$number=trim($_GET['document']??'');$stmt=db()->prepare('SELECT d.*,r.full_name,r.barangay_id,v.verification_token,v.revoked_at FROM document_requests d LEFT JOIN residents r ON r.id=d.resident_id LEFT JOIN document_verifications v ON v.document_request_id=d.id WHERE d.document_no=? LIMIT 1');$stmt->execute([$number]);$document=$stmt->fetch();$valid=$document&&$document['status']==='Issued'&&!$document['revoked_at'];
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Document verification · Barangay</title><link rel="stylesheet" href="assets/app.css"></head><body class="login-page"><div class="login-card"><div class="brand login-brand"><div class="brand-mark"><span></span><span></span></div><div><strong>Barangay</strong><small>document verification</small></div></div><div class="eyebrow">Public verification</div><h1><?= $valid?'Document is valid.':'Document not verified.' ?></h1><?php if($valid): ?><p class="login-copy">This record matches the barangay issuance register.</p><div class="demo-note"><strong><?= h($document['document_no']) ?></strong><span><?= h($document['document_type']) ?> · <?= h($document['full_name']) ?> · Issued <?= h(date('M d, Y',strtotime($document['released_at']))) ?></span></div><?php else: ?><p class="login-copy">Enter the official document number exactly as printed on the document.</p><form class="login-form"><label>Official document number<input name="document" required value="<?= h($number) ?>"></label><button class="primary-button full-button">Verify document</button></form><?php endif; ?></div></body></html>
